#define DOME_JOINT_SOURCE_EMBEDDED
#include "source-joint-writable-normal-bake.cpp"
#undef DOME_JOINT_SOURCE_EMBEDDED
namespace {
size_t controls=0;
void hdr_check(bool ok,const char*why){if(!ok)throw std::runtime_error(why);++controls;}
bool rejected(auto operation){try{operation();return false;}catch(const std::exception&error){std::cout<<"HDR_EXPECTED_REFUSAL "<<error.what()<<std::endl;return true;}}
std::array<double,2> coordinates(const SculptObject&o,size_t triangle,std::array<float,3>bary){const auto&m=o.painted->mesh();std::array<double,2>uv{};for(size_t k=0;k<3;++k)for(size_t axis=0;axis<2;++axis)uv[axis]+=double(m.uv[m.indices[triangle*3+k]][axis])*bary[k];return uv;}
double coverage(const PaintedMesh&p,std::array<double,2>uv){const int r=p.resolution();const double x=uv[0]*r-.5,y=uv[1]*r-.5;const int ix=int(std::floor(x)),iy=int(std::floor(y));double result=0;for(int dy=0;dy<2;++dy)for(int dx=0;dx<2;++dx){const int px=std::clamp(ix+dx,0,r-1),py=std::clamp(iy+dy,0,r-1);double alpha=0;for(const auto&layer:p.layers())if(layer.visible&&layer.opacity){const auto e=p.emission_pixel(layer.id,px,py);const double a=double(e.coverage)*p.pixel(layer.id,px,py).data[13]/255.*layer.opacity;alpha=alpha*(1-a)+a;}result+=alpha*(dx?x-ix:1-(x-ix))*(dy?y-iy:1-(y-iy));}return result;}
nlohmann::json&payload(nlohmann::json&scene,uint64_t id){auto*root=&scene;while(root->contains("payload"))root=&root->at("payload");for(auto&object:root->at("objects"))if(object.at("id")==id){auto*paint=&object.at("painted");while(paint->contains("payload"))paint=&paint->at("payload");return paint->at("baked");}throw std::runtime_error("Missing actual HDR target");}
}
int main(int argc,char**argv)try{
 if(argc!=3)return 2;const std::filesystem::path input=argv[1],out=argv[2];std::filesystem::create_directories(out);
 auto scene=Scene::load(input);const auto target=scene.active().id;const auto baked=scene.active().painted->baked();hdr_check(baked&&baked->emission_domain&&!baked->emission_field,"Actual accepted source domain is the sole emission authority");const auto domain=baked->emission_domain;const auto source=domain->source_id();hdr_check(domain->field()->resolution()==64&&scene.active().painted->resolution()==512&&scene.object(source).painted->resolution()==64,"Certified higher normal/paint target retains genuine64 physical knots");const auto original=scene.encode();auto schema=original;hdr_check(original.at("version")==43&&payload(schema,target).at("version")==7,"Actual new domain persists through explicit Scene43/payload7");
 auto missing=scene.active().bake_recipe->encode();missing["settings"].erase("emission_transport");const auto legacy=ObjectBakeRecipe::decode(missing);hdr_check(legacy->settings.emission_transport==0&&legacy->encode()==missing&&ObjectBakeSettings{}.emission_transport==1,"Absent HDR recipe policy remains byte-equivalent legacy0; new request is explicit1");
 const auto proof=domain->encode();const auto copy=scene.active().painted->snapshot();domain->validate_current(copy->mesh_owner(),copy->resolution());hdr_check(true,"Detached wrapper snapshot retains exact current geometry authority");const auto foreign=std::make_shared<const Mesh>(copy->mesh());hdr_check(rejected([&]{domain->validate_current(foreign,512);})&&scene.encode()==original,"Equal geometry bytes cannot borrow a foreign current owner");
 for(int fault=0;fault<4;++fault){auto forged=original;if(fault==0)forged["version"]=41;else if(fault==1)payload(forged,target)["emission_domain"]["source"]=uint64_t(999999);else if(fault==2)payload(forged,target)["emission_domain"]["resolution"]=128;else payload(forged,target).erase("emission_domain");hdr_check(rejected([&]{Scene::decode(forged);})&&scene.encode()==original,"Malformed or borrowed native HDR authority refuses without source mutation");}
 auto alias_scene=Scene::load(input.parent_path()/"selected-target-resolution.dsculpt");auto binding=std::make_shared<SourceMaterialBindings>(*alias_scene.object(source).material_bindings);alias_scene.object(source).material_bindings=binding;const auto settings=scene.active().bake_recipe->settings;bake_object(alias_scene,source,settings);const auto alias_domain=alias_scene.active().painted->baked()->emission_domain;hdr_check(bool(alias_domain),"Actual Bake captures a source whose external DTO alias predates capture");const auto alias_proof=alias_domain->encode();
 binding->physical_emission=std::array<float,3>{7,5,3};hdr_check(alias_domain->encode()==alias_proof,"Preexisting mutable material DTO alias cannot change captured before provenance");
 auto changed=scene.snapshot();changed.active().material.emissive={17,8,3};const auto pure=detail::emission_bake_source(changed.active());hdr_check(bool(pure),"Current material sampler captures actual source-domain coefficients");double material_error=0;for(size_t tri=0;tri<changed.active().painted->mesh().indices.size()/3;++tri){const std::array<float,3>bary{.25f,.35f,.4f};const auto q=coordinates(changed.active(),tri,bary);const auto expected=domain->field()->sample(float(q[0]),float(q[1])).resolve({},1);const auto actual=pure(uint32_t(tri),bary);for(size_t c=0;c<3;++c)material_error=std::max(material_error,std::abs(double(expected[c])-actual[c]));}hdr_check(material_error<2e-4,"Captured absolute emission survives later target material factors");
 auto paint=changed.active().painted->snapshot();paint->add_layer("Actual current512 emission above retained64");PaintSettings ink;ink.front_only=false;ink.channel=PaintChannel::Emission;ink.emission_units=PaintEmissionUnits::Physical;ink.emission={.25f,6,2};Brush brush;brush.from=brush.to={0,0,.2f};brush.normal={0,0,1};brush.radius=.18f;brush.strength=.8f;paint->begin_stroke();paint->stamp(brush,ink);hdr_check(paint->end_stroke(),"Actual separate512 physical paint layer commits");changed.active().painted=paint;changed.validate();const auto sampler=detail::emission_bake_source(changed.active());double overlay_error=0,max_coverage=0;size_t samples=0;
 for(size_t tri=0;tri<paint->mesh().indices.size()/3;++tri)for(int y=1;y<16;++y)for(int x=1;x<16-y;++x){const std::array<float,3>bary{float(x)/16,float(y)/16,1-float(x+y)/16};const auto q=coordinates(changed.active(),tri,bary);const auto root=joint_source::paint_uv(changed.object(source),tri,bary);const auto below=joint_source::physical(*changed.object(source).painted,root),above=joint_source::physical(*paint,q);const auto a=coverage(*paint,q);const auto actual=sampler(uint32_t(tri),bary);for(size_t c=0;c<3;++c)overlay_error=std::max(overlay_error,std::abs(below[c]*(1-a)+above[c]-actual[c]));max_coverage=std::max(max_coverage,a);++samples;}
 hdr_check(samples>1000&&max_coverage>.2&&overlay_error<2e-4,"Independent source64 plus current512 layer equation retains unchanged HDR bound");const auto edited=changed.encode();changed.save(out/"layered-domain.dsculpt");hdr_check(Scene::load(out/"layered-domain.dsculpt").encode()==edited,"Multi-grid layer Save/reopen owns every coefficient and source identity");hdr_check(domain->encode()==proof&&scene.encode()==original,"Editing and Save preserve original scene and immutable source provenance");
 std::cout<<std::setprecision(12)<<"HDR_DOMAIN_CONTROLS samples="<<samples<<" material_error="<<material_error<<" overlay_error="<<overlay_error<<" max_coverage="<<max_coverage<<std::endl;std::cout<<"PASS "<<controls<<" owning HDR-domain controls"<<std::endl;return 0;
}catch(const std::exception&error){std::cerr<<"FAIL "<<error.what()<<std::endl;return 1;}
